import React, { useState, useRef, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { createMess, editMess, getUploadUrl, getItemById } from '../../api/listingService';
import { toast } from "sonner";
import { useAuth } from '../../context/AuthContext';
import { useGoogleMaps, MAP_ID } from '../../context/GoogleMapsContext';
import { Autocomplete, GoogleMap } from '@react-google-maps/api';
import AdvancedMarker from '../common/AdvancedMarkerMap';
import { FaLeaf, FaDrumstickBite, FaUtensils, FaPlus, FaTimes, FaCheck, FaRupeeSign, FaInfoCircle, FaMapPin } from 'react-icons/fa';
import { MapPin } from 'lucide-react';
import { Button } from "../../components/ui/button";
import { Input } from "../../components/ui/input";
import { Textarea } from "../../components/ui/textarea";
import { Checkbox } from "../../components/ui/checkbox";
import { Label } from "../../components/ui/label";
import { cn } from "../../lib/utils";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from "../../components/ui/dialog";



// Helper Component for Menu Toggles (Veg/Non-Veg)
const MessTypeToggle = ({ icon: Icon, title, isActive, onClick }) => (
    <div
        onClick={onClick}
        className={cn(
            "flex items-center gap-3 p-3 rounded-xl border-2 transition-all cursor-pointer shadow-md",
            isActive
                ? "border-amber-500 bg-gradient-to-r from-green-700 to-green-800 text-white scale-[1.03]"
                : "border-gray-300 bg-white text-gray-700 hover:bg-gray-50"
        )}
    >
        <div className={cn(
            "w-8 h-8 rounded-full flex items-center justify-center",
            isActive ? "bg-white" : "bg-gray-100"
        )}>
            <Icon size={18} className={title.includes("Veg") ? "text-green-600" : "text-red-500"} />
        </div>
        <p className="font-bold text-lg">{title}</p>
    </div>
);

// Menu Item Selection Component
const MenuItemSelector = ({
    title,
    items,
    selectedItems,
    onToggle,
    onCustomAdd,
    customItems,
    onCustomRemove
}) => {
    const [showCustomInput, setShowCustomInput] = useState(false);
    const [customItem, setCustomItem] = useState('');

    const handleAddCustom = () => {
        if (customItem.trim() && !customItems.includes(customItem.trim())) {
            onCustomAdd(customItem.trim());
            setCustomItem('');
            setShowCustomInput(false);
        }
    };

    return (
        <div className="space-y-3">
            <h3 className="font-serif text-xl font-bold text-gray-800 flex items-center gap-2">
                <FaUtensils className={title.includes("Veg") ? "text-green-600" : "text-red-500"} />
                {title}
            </h3>

            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                {items.map((item, index) => (
                    <Button
                        key={index}
                        type="button"
                        variant={selectedItems.includes(item) ? "secondary" : "outline"}
                        onClick={() => onToggle(item)}
                        className={cn(
                            "p-2 rounded-lg border text-left justify-between h-auto",
                            selectedItems.includes(item) && "border-amber-400 bg-amber-50 text-amber-800 font-medium"
                        )}
                    >
                        {item}
                        {selectedItems.includes(item) && <FaCheck className="text-amber-500" />}
                    </Button>
                ))}
            </div>

            <div className="space-y-2 mt-2">
                {customItems.map((item, index) => (
                    <div key={`custom-${index}`} className="flex items-center gap-2 bg-gray-100 p-2 rounded-lg">
                        <span className="flex-1 font-medium">{item}</span>
                        <Button
                            size="icon"
                            variant="ghost"
                            onClick={() => onCustomRemove(item)}
                            className="h-7 w-7"
                        >
                            <FaTimes className="text-red-500" />
                        </Button>
                    </div>
                ))}

                {showCustomInput ? (
                    <div className="flex gap-2">
                        <Input
                            value={customItem}
                            onChange={(e) => setCustomItem(e.target.value)}
                            placeholder="Enter custom item..."
                            onKeyDown={(e) => e.key === 'Enter' && handleAddCustom()}
                            className="bg-white"
                        />
                        <Button onClick={handleAddCustom} className="bg-primary hover:bg-primary/90">
                            Add
                        </Button>
                    </div>
                ) : (
                    <Button
                        variant="outline"
                        onClick={() => setShowCustomInput(true)}
                        className="border-dashed border-2 w-full bg-gray-50 hover:bg-gray-100"
                    >
                        <FaPlus className="mr-2" /> Add Custom Item
                    </Button>
                )}
            </div>
        </div>
    );
};

// Day Selection Component
const DaySelector = ({ selectedDays, onToggle }) => {
    const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <div className="space-y-3">
            <h3 className="font-serif text-xl font-bold text-gray-800">Non-Veg Days</h3>
            <p className="text-sm text-gray-600 mb-2">Select days when non-veg items are served</p>

            <div className="flex flex-wrap gap-2">
                {days.map((day) => (
                    <Button
                        key={day}
                        type="button"
                        variant={selectedDays.includes(day) ? "default" : "outline"}
                        size="icon"
                        onClick={() => onToggle(day)}
                        className={cn(
                            "w-10 h-10 rounded-full font-bold text-lg",
                            selectedDays.includes(day) && "bg-red-500 hover:bg-red-600 text-white"
                        )}
                    >
                        {day}
                    </Button>
                ))}
            </div>
        </div>
    );
};

// Pricing Options Component
const PricingOptions = ({
    fullTiffin2TimePrice,
    setFullTiffin2TimePrice,
    halfTiffin2TimePrice,
    setHalfTiffin2TimePrice,
    offerOneTimeMeal,
    setOfferOneTimeMeal,
    fullTiffin1TimePrice,
    setFullTiffin1TimePrice,
    halfTiffin1TimePrice,
    setHalfTiffin1TimePrice
}) => {
    return (
        <div className="space-y-6 pt-4">
            {/* Monthly Fees (2 Times) Section */}
            <div className="space-y-3 border-b border-gray-200 pb-4">
                <h3 className="font-serif text-xl font-bold text-gray-800 flex items-center gap-2">
                    <span>💰</span> Monthly Fees (2 Times Meal)
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    {/* Full Tiffin (2 Times) */}
                    <div className="space-y-2">
                        <label className="font-medium text-gray-700">Full Tiffin (Mandatory)</label>
                        <div className="relative">
                            <Input
                                type="number"
                                value={fullTiffin2TimePrice}
                                onChange={(e) => setFullTiffin2TimePrice(e.target.value)}
                                placeholder="3500"
                                className="pl-10"
                                required
                            />
                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold">₹</span>
                        </div>
                        <p className="text-xs text-gray-500">Price for full tiffin (2 meals per day)</p>
                    </div>

                    {/* Half Tiffin (2 Times) */}
                    <div className="space-y-2">
                        <label className="font-medium text-gray-700">Half Tiffin (Optional)</label>
                        <div className="relative">
                            <Input
                                type="number"
                                value={halfTiffin2TimePrice}
                                onChange={(e) => setHalfTiffin2TimePrice(e.target.value)}
                                placeholder="2000"
                                className="pl-10"
                            />
                            <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold">₹</span>
                        </div>
                        <p className="text-xs text-gray-500">Price for half tiffin (2 meals per day)</p>
                    </div>
                </div>
            </div>

            {/* One Time Meal Option */}
            <div className="space-y-3">
                <div className="flex items-center gap-3">
                    <Checkbox
                        id="oneTimeMeal"
                        checked={offerOneTimeMeal}
                        onCheckedChange={setOfferOneTimeMeal}
                    />
                    <Label htmlFor="oneTimeMeal" className="font-medium text-gray-700 cursor-pointer">
                        Offer One-Time Meal Plan?
                    </Label>
                </div>

                {offerOneTimeMeal && (
                    <div className="pt-3 border-t border-gray-200">
                        <h3 className="font-serif text-xl font-bold text-gray-800 flex items-center gap-2 mb-3">
                            <span>💰</span> Monthly Fees (1 Time Meal)
                        </h3>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                            {/* Full Tiffin (1 Time) */}
                            <div className="space-y-2">
                                <label className="font-medium text-gray-700">Full Tiffin (Mandatory)</label>
                                <div className="relative">
                                    <Input
                                        type="number"
                                        value={fullTiffin1TimePrice}
                                        onChange={(e) => setFullTiffin1TimePrice(e.target.value)}
                                        placeholder="3000"
                                        className="pl-10"
                                        required
                                    />
                                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold">₹</span>
                                </div>
                                <p className="text-xs text-gray-500">Price for full tiffin (1 meal per day)</p>
                            </div>

                            {/* Half Tiffin (1 Time) */}
                            <div className="space-y-2">
                                <label className="font-medium text-gray-700">Half Tiffin (Optional)</label>
                                <div className="relative">
                                    <Input
                                        type="number"
                                        value={halfTiffin1TimePrice}
                                        onChange={(e) => setHalfTiffin1TimePrice(e.target.value)}
                                        placeholder="1500"
                                        className="pl-10"
                                    />
                                    <span className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-500 font-bold">₹</span>
                                </div>
                                <p className="text-xs text-gray-500">Price for half tiffin (1 meal per day)</p>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </div>
    );
};

const CreateMessForm = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [searchParams] = useSearchParams();
  const editMessId = searchParams.get('edit');
  const isEditMode = !!editMessId;

    const [name, setName] = useState('');
    const [description, setDescription] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isLoadingData, setIsLoadingData] = useState(false);
    const [location, setLocation] = useState(null);
    const [address, setAddress] = useState("");
    const [mapCenter, setMapCenter] = useState({ lat: 18.5204, lng: 73.8567 });
    const [selectedMessType, setSelectedMessType] = useState('veg');
    const [coverPhoto, setCoverPhoto] = useState(null);
    const [otherPhotos, setOtherPhotos] = useState([]);
    const searchBoxRef = useRef(null);
    const [isConfirmOpen, setIsConfirmOpen] = useState(false);

    // Menu State
    const [vegItems, setVegItems] = useState([]);
    const [nonVegItems, setNonVegItems] = useState([]);
    const [nonVegDays, setNonVegDays] = useState([]);
    const [customVegItems, setCustomVegItems] = useState([]);
    const [customNonVegItems, setCustomNonVegItems] = useState([]);

    // Pricing State
    const [fullTiffin2TimePrice, setFullTiffin2TimePrice] = useState('');
    const [halfTiffin2TimePrice, setHalfTiffin2TimePrice] = useState('');
    const [offerOneTimeMeal, setOfferOneTimeMeal] = useState(false);
    const [fullTiffin1TimePrice, setFullTiffin1TimePrice] = useState('');
    const [halfTiffin1TimePrice, setHalfTiffin1TimePrice] = useState('');

    // Preview States
    const [coverPhotoPreview, setCoverPhotoPreview] = useState(null);
    const [otherPhotosPreviews, setOtherPhotosPreviews] = useState([]);
    const [mapInstance, setMapInstance] = useState(null);
    const [mapError, setMapError] = useState(false);
    const [existingCoverUrl, setExistingCoverUrl] = useState('');
    const [existingOtherUrls, setExistingOtherUrls] = useState([]);

    // Predefined menu items
    const VEG_ITEMS = ['Roti', 'Rice', 'Dal', 'Sabji', 'Salad', 'Butter Milk', 'Paneer', 'Pickle', 'Sweet'];
    const NON_VEG_ITEMS = ['Chicken Curry', 'Egg Curry', 'Fish Fry', 'Mutton', 'Biryani', 'Soup'];

    // Load existing mess data in edit mode
    useEffect(() => {
        if (isEditMode && editMessId) {
            const loadMessData = async () => {
                setIsLoadingData(true);
                try {
                    const mess = await getItemById('mess', editMessId);
                    if (mess) {
                        setName(mess.name || '');
                        setDescription(mess.description || '');
                        setAddress(mess.address || '');
                        setLocation(mess.location ? { lat: mess.location.lat, lng: mess.location.lng } : null);

                        // Load menu data
                        if (mess.menu) {
                            setSelectedMessType(mess.menu.type || 'veg');
                            setVegItems(mess.menu.vegItems || []);
                            setNonVegItems(mess.menu.nonVegItems || []);
                            setNonVegDays(mess.menu.nonVegDays || []);
                        }

                        // Load pricing data
                        if (mess.pricing) {
                            if (mess.pricing.monthlyTwoTime) {
                                setFullTiffin2TimePrice(mess.pricing.monthlyTwoTime.fullTiffin?.toString() || '');
                                setHalfTiffin2TimePrice(mess.pricing.monthlyTwoTime.halfTiffin?.toString() || '');
                            }
                            if (mess.pricing.monthlyOneTime) {
                                setOfferOneTimeMeal(true);
                                setFullTiffin1TimePrice(mess.pricing.monthlyOneTime.fullTiffin?.toString() || '');
                                setHalfTiffin1TimePrice(mess.pricing.monthlyOneTime.halfTiffin?.toString() || '');
                            }
                        }

                        setExistingCoverUrl(mess.cover_photo_url || '');
                        setExistingOtherUrls(mess.other_photos_urls || []);
                        setCoverPhotoPreview(mess.cover_photo_url || null);
                        setOtherPhotosPreviews(mess.other_photos_urls || []);
                    }
                } catch (error) {
                    toast.error('Failed to load mess data');
                    navigate('/owner/mess');
                } finally {
                    setIsLoadingData(false);
                }
            };
            loadMessData();
        }
}, [isEditMode, editMessId, navigate]);

// Redirect unauthorized users (only block creation, not editing existing mess)
useEffect(() => {
const serviceType = user?.serviceType;
if (serviceType === 'room') {
toast.error('You are not authorized to create mess listings. Please use your rooms dashboard.');
navigate('/owner/rooms');
} else if (!isEditMode && serviceType !== 'mess' && serviceType !== 'both') {
toast.error('Please complete your profile to create mess listings.');
navigate('/owner/mess');
}
}, [user, isEditMode, navigate]);

// Cleanup object URLs to prevent memory leaks
    useEffect(() => {
        return () => {
            if (coverPhotoPreview && !coverPhotoPreview.startsWith('http')) {
                URL.revokeObjectURL(coverPhotoPreview);
            }
            otherPhotosPreviews.forEach(url => {
                if (!url.startsWith('http')) {
                    URL.revokeObjectURL(url);
                }
            });
        };
    }, [coverPhotoPreview, otherPhotosPreviews]);

    const { isLoaded, loadError, isMapsAvailable } = useGoogleMaps();

    const handleMapLoad = (map) => {
        setMapInstance(map);
        setMapError(false);
    };

    const handleMapError = (error) => {
        console.error('Google Maps error:', error);
        setMapError(true);
    };

    const handleMarkerError = (error) => {
        console.warn('Marker error:', error);
        setMapError(true);
    };

    // Image handling functions
    const handleCoverPhotoChange = (e) => {
        const file = e.target.files[0];
        if (file) {
            setCoverPhoto(file);
            setCoverPhotoPreview(URL.createObjectURL(file));
        }
    };

    const handleOtherPhotosChange = (e) => {
        const files = Array.from(e.target.files);

        // Check total photos after adding new ones
        if (otherPhotos.length + files.length > 6) {
            toast.error('You can only upload up to 6 additional photos');
            return;
        }

        setOtherPhotos(prev => [...prev, ...files]);
        const newPreviews = files.map(file => URL.createObjectURL(file));
        setOtherPhotosPreviews(prev => [...prev, ...newPreviews]);
    };

    const removeOtherPhoto = (indexToRemove) => {
        // Revoke URL of removed photo to prevent memory leak
        const photoToRemove = otherPhotosPreviews[indexToRemove];
        if (photoToRemove) {
            URL.revokeObjectURL(photoToRemove);
        }

        setOtherPhotos(prev => prev.filter((_, index) => index !== indexToRemove));
        setOtherPhotosPreviews(prev => prev.filter((_, index) => index !== indexToRemove));
    };

    // Menu handling functions
    const toggleVegItem = (item) => {
        setVegItems(prev =>
            prev.includes(item) ? prev.filter(i => i !== item) : [...prev, item]
        );
    };

    const toggleNonVegItem = (item) => {
        setNonVegItems(prev =>
            prev.includes(item) ? prev.filter(i => i !== item) : [...prev, item]
        );
    };

    const toggleNonVegDay = (day) => {
        setNonVegDays(prev =>
            prev.includes(day) ? prev.filter(d => d !== day) : [...prev, day]
        );
    };

    const addCustomVegItem = (item) => {
        if (!customVegItems.includes(item)) {
            setCustomVegItems(prev => [...prev, item]);
        }
    };

    const addCustomNonVegItem = (item) => {
        if (!customNonVegItems.includes(item)) {
            setCustomNonVegItems(prev => [...prev, item]);
        }
    };

    const removeCustomVegItem = (item) => {
        setCustomVegItems(prev => prev.filter(i => i !== item));
    };

    const removeCustomNonVegItem = (item) => {
        setCustomNonVegItems(prev => prev.filter(i => i !== item));
    };

    // Google Maps functions
    const handlePlaceSelect = () => {
        const place = searchBoxRef.current.getPlace();
        if (place && place.geometry) {
            const lat = place.geometry.location.lat();
            const lng = place.geometry.location.lng();
            setAddress(place.formatted_address);
            setLocation({ lat, lng });
            setMapCenter({ lat, lng });
        }
    };

    const handleMapClick = (e) => {
        const lat = e.latLng.lat();
        const lng = e.latLng.lng();
        setLocation({ lat, lng });
        setMapCenter({ lat, lng });
    };

    const handleMarkerDragEnd = (e) => {
        const lat = e.latLng.lat();
        const lng = e.latLng.lng();
        setLocation({ lat, lng });
        setMapCenter({ lat, lng });
    };

    // Form submission
    const handleSubmit = async (e) => {
        e.preventDefault();

        // In edit mode, cover photo is optional (existing photo will be used)
        if (!isEditMode && !coverPhoto) {
            toast.error('Please select a cover photo.');
            return;
        }

        if (!location) {
            toast.error('Please select a location.');
            return;
        }
        if (!name || !fullTiffin2TimePrice) {
            toast.error('Please fill in all required fields, including Full Tiffin price for 2-times meal plan.');
            return;
        }
        if ((selectedMessType === 'both' || selectedMessType === 'non-veg') && nonVegDays.length === 0) {
            toast.error('Please select at least one non-veg day.');
            return;
        }
        if (offerOneTimeMeal && !fullTiffin1TimePrice) {
            toast.error('Full Tiffin price is required for the one-time meal plan.');
            return;
        }
        setIsConfirmOpen(true);
    };

    const handleConfirmSubmit = async () => {
        setIsLoading(true);
        setIsConfirmOpen(false);
        try {
            let finalCoverUrl = existingCoverUrl;
            let finalOtherUrls = [...existingOtherUrls];

            // Upload new cover photo if changed
            if (coverPhoto) {
                const coverToast = toast.loading('Uploading cover photo...');
                try {
                    const uploadRes = await getUploadUrl(coverPhoto.type, 'mess');
                    const coverUploadUrl = uploadRes?.uploadUrl;
                    const newCoverUrl = uploadRes?.imageUrl || uploadRes?.finalUrl;
                    if (coverUploadUrl && !coverUploadUrl.includes('mock')) {
                        try {
                            await fetch(coverUploadUrl, {
                                method: 'PUT',
                                body: coverPhoto,
                                headers: { 'Content-Type': coverPhoto.type }
                            });
                        } catch (e) {
                            console.info("Demo Mode: Simulating cover photo upload", e);
                        }
                    }
                    finalCoverUrl = newCoverUrl || (typeof coverPhoto === 'string' ? coverPhoto : URL.createObjectURL(coverPhoto));
                } finally {
                    toast.dismiss(coverToast);
                }
            }

            // Upload new other photos
            if (otherPhotos.length > 0) {
                const otherToast = toast.loading(`Uploading ${otherPhotos.length} additional photos...`);
                try {
                    const newPhotoUrls = await Promise.all(
                        otherPhotos.map(async (photo) => {
                            const uploadRes = await getUploadUrl(photo.type, 'mess');
                            const uploadUrl = uploadRes?.uploadUrl;
                            const imageUrl = uploadRes?.imageUrl || uploadRes?.finalUrl;
                            if (uploadUrl && !uploadUrl.includes('mock')) {
                                try {
                                    await fetch(uploadUrl, {
                                        method: 'PUT',
                                        body: photo,
                                        headers: { 'Content-Type': photo.type }
                                    });
                                } catch (e) {
                                    console.info("Demo Mode: Simulating additional photo upload", e);
                                }
                            }
                            return imageUrl || (typeof photo === 'string' ? photo : URL.createObjectURL(photo));
                        })
                    );
                    finalOtherUrls = [...existingOtherUrls, ...newPhotoUrls];
                } finally {
                    toast.dismiss(otherToast);
                }
            }

            // Prepare menu data
            const menuData = {
                type: selectedMessType,
                vegItems: [...vegItems, ...customVegItems],
                nonVegItems: (selectedMessType === 'both' || selectedMessType === 'non-veg') ? [...nonVegItems, ...customNonVegItems] : [],
                nonVegDays: (selectedMessType === 'both' || selectedMessType === 'non-veg') ? nonVegDays : [],
            };

            // Prepare pricing data
            const pricingData = {
                monthlyTwoTime: {
                    fullTiffin: Number(fullTiffin2TimePrice),
                    halfTiffin: halfTiffin2TimePrice ? Number(halfTiffin2TimePrice) : null
                },
                monthlyOneTime: offerOneTimeMeal ? {
                    fullTiffin: Number(fullTiffin1TimePrice),
                    halfTiffin: halfTiffin1TimePrice ? Number(halfTiffin1TimePrice) : null
                } : null,
            };

            // Prepare final data
            const messData = {
                mess_id: isEditMode ? editMessId : undefined,
                name,
                price_per_month: Number(fullTiffin2TimePrice),
                description,
                address,
                location: { lat: location.lat, lng: location.lng },
                menu: menuData,
                pricing: pricingData,
                cover_photo_url: finalCoverUrl,
                other_photos_urls: finalOtherUrls,
                status: isEditMode ? undefined : 'pending'
            };

            // Submit to backend
            const saveToast = toast.loading('Saving mess details...');

            if (isEditMode) {
                await editMess(messData);
                toast.dismiss(saveToast);
                toast.success('Mess updated successfully!');
            } else {
                await createMess(messData);
                toast.dismiss(saveToast);
                toast.success('Your mess listing has been submitted for approval!');
            }
            navigate('/owner/mess');
        } catch (error) {
            toast.dismiss();
            toast.error(error.message || `Failed to ${isEditMode ? 'update' : 'create'} mess listing. Please try again.`);
            console.error("Mess Error:", error);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="min-h-[calc(100vh-64px)] py-8 px-4 bg-[#d4c6a6]">
            {/* Loading State */}
            {isLoadingData ? (
                <div className="flex justify-center items-center min-h-[50vh]">
                    <div className="space-y-4 w-full max-w-lg">
                        <div className="h-10 w-64 bg-gray-200 rounded animate-pulse mx-auto"></div>
                        <div className="h-80 bg-gray-200 rounded-xl animate-pulse"></div>
                    </div>
                </div>
            ) : (
                <>
                    {/* Header */}
                    <div className="text-center mb-8">
                        <h1 className="text-4xl md:text-5xl font-serif font-bold text-gray-800 mb-2">
                            {isEditMode ? 'Edit Your Mess Listing' : 'Create Your Mess Listing'}
                        </h1>
                        <p className="text-gray-600 max-w-2xl mx-auto">
                            {isEditMode
                                ? 'Update your mess details below. Changes may require re-approval.'
                                : 'Fill in the details below to create your mess listing. All fields marked with * are required.'}
                        </p>
                    </div>

                    {/* Main Form Container - Full Width */}
                    <div className="w-full max-w-full mx-auto px-4">
                        <div className="bg-white rounded-3xl shadow-xl overflow-hidden border-4 border-[#e9d29f]">
                            {/* Cover Photo Section */}
                            <div className="bg-gradient-to-r from-green-50 to-amber-50 py-6 px-4 md:px-6 border-b border-gray-200">
                                <div className="flex flex-col md:flex-row gap-6 items-center">
                                    {/* Cover Photo */}
                                    <div className="w-full flex flex-col items-center">
                                        <div className="relative w-full h-72 md:h-96 bg-gray-100 rounded-2xl border-2 border-dashed border-gray-400 flex flex-col items-center justify-center overflow-hidden">
                                            {coverPhotoPreview ? (
                                                <>
                                                    <img
                                                        src={coverPhotoPreview}
                                                        alt="Cover Preview"
                                                        className="w-full h-full object-cover"
                                                    />
                                                    <Button
                                                        type="button"
                                                        variant="ghost"
                                                        size="icon"
                                                        onClick={() => {
                                                            setCoverPhoto(null);
                                                            setCoverPhotoPreview(null);
                                                        }}
                                                        className="absolute top-2 right-2 h-8 w-8 rounded-full bg-red-500 text-white hover:bg-red-600"
                                                    >
                                                        <FaTimes size={14} />
                                                    </Button>
                                                </>
                                            ) : (
                                                <>
                                                    <input
                                                        type="file"
                                                        id="coverPhoto"
                                                        className="sr-only"
                                                        onChange={handleCoverPhotoChange}
                                                        accept="image/*"
                                                        required
                                                    />
                                                    <label
                                                        htmlFor="coverPhoto"
                                                        className="flex flex-col items-center justify-center w-full h-full cursor-pointer"
                                                    >
                                                        <FaPlus size={64} className="text-gray-400 mb-2" />
                                                        <p className="text-gray-600 font-medium">Add Cover Photo</p>
                                                        <p className="text-xs text-gray-500 mt-1">Recommended: 1200x800px</p>
                                                    </label>
                                                </>
                                            )}
                                        </div>
                                        <p className="text-xs text-gray-500 mt-2 text-center">
                                            This will be the main photo for your listing. Make sure it's well-lit and shows your room clearly.
                                        </p>
                                    </div>

                                    {/* Other Photos */}
                                    <div className="w-full">
                                        <div className="bg-white rounded-2xl border border-gray-200 p-4 flex flex-col">
                                            <div className="flex items-center justify-between mb-4">
                                                <h3 className="font-serif text-xl font-bold text-gray-800">Additional Photos</h3>
                                                <label
                                                    htmlFor="otherPhotos"
                                                    className="cursor-pointer bg-primary text-white px-3 py-1 rounded-lg text-sm font-medium hover:bg-primary/90 transition-colors flex items-center gap-1"
                                                >
                                                    <FaPlus size={14} /> Add Photos
                                                    <input
                                                        type="file"
                                                        id="otherPhotos"
                                                        className="sr-only"
                                                        multiple
                                                        onChange={handleOtherPhotosChange}
                                                        accept="image/*"
                                                    />
                                                </label>
                                            </div>

                                            {otherPhotosPreviews.length > 0 ? (
                                                <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3 flex-1 min-h-[150px] overflow-y-auto pr-2">
                                                    {otherPhotosPreviews.map((url, index) => (
                                                        <div key={index} className="relative aspect-square rounded-lg overflow-hidden border border-gray-200">
                                                            <img
                                                                src={url}
                                                                alt={`Preview ${index}`}
                                                                className="w-full h-full object-cover"
                                                            />
                                                            <Button
                                                                type="button"
                                                                variant="ghost"
                                                                size="icon"
                                                                onClick={() => removeOtherPhoto(index)}
                                                                className="absolute top-1 right-1 h-6 w-6 rounded-full bg-red-500 text-white hover:bg-red-600"
                                                            >
                                                                <FaTimes size={12} />
                                                            </Button>
                                                        </div>
                                                    ))}
                                                </div>
                                            ) : (
                                                <div className="flex-1 flex flex-col items-center justify-center text-center text-gray-500">
                                                    <FaPlus size={32} className="mb-2 opacity-50" />
                                                    <p>Add photos of your room, bathroom, common areas, and amenities</p>
                                                </div>
                                            )}

                                            <p className="text-xs text-gray-500 mt-3">
                                                You can add up to 6 additional photos. Show your room from different angles!
                                            </p>
                                        </div>
                                    </div>
                                </div>
                            </div>

                            {/* Form Content - Two Column Layout */}
                            <div className="p-4 md:p-6">
                                <form onSubmit={handleSubmit} className="space-y-6">
                                    {/* Two Column Layout */}
                                    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                                        {/* Left Column - Menu Details */}
                                        <div className="space-y-4">
                                            {/* Mess Type Selection */}
                                            <div className="space-y-4">
                                                <h2 className="font-serif text-2xl font-bold text-gray-800 flex items-center gap-2">
                                                    <span className="bg-amber-100 text-amber-800 rounded-full p-1">
                                                        <FaUtensils size={20} />
                                                    </span>
                                                    Menu Configuration
                                                </h2>

                                                <div className="flex flex-wrap gap-3">
                                                    <MessTypeToggle
                                                        icon={FaLeaf}
                                                        title="Only Veg"
                                                        isActive={selectedMessType === 'veg'}
                                                        onClick={() => setSelectedMessType('veg')}
                                                    />
                                                    <MessTypeToggle
                                                        icon={FaDrumstickBite}
                                                        title="Non-Veg Only"
                                                        isActive={selectedMessType === 'non-veg'}
                                                        onClick={() => setSelectedMessType('non-veg')}
                                                    />
                                                    <MessTypeToggle
                                                        icon={FaUtensils}
                                                        title="Veg & Non-Veg"
                                                        isActive={selectedMessType === 'both'}
                                                        onClick={() => setSelectedMessType('both')}
                                                    />
                                                </div>
                                            </div>

                                            {/* Menu Items */}
                                            {selectedMessType === 'veg' ? (
                                                <MenuItemSelector
                                                    title="Veg Menu Items"
                                                    items={VEG_ITEMS}
                                                    selectedItems={vegItems}
                                                    onToggle={toggleVegItem}
                                                    onCustomAdd={addCustomVegItem}
                                                    customItems={customVegItems}
                                                    onCustomRemove={removeCustomVegItem}
                                                />
                                            ) : (
                                                <>
                                                    <DaySelector
                                                        selectedDays={nonVegDays}
                                                        onToggle={toggleNonVegDay}
                                                    />

                                                    <div className="space-y-6 pt-4 border-t border-gray-200">
                                                        <MenuItemSelector
                                                            title="Veg Menu Items"
                                                            items={VEG_ITEMS}
                                                            selectedItems={vegItems}
                                                            onToggle={toggleVegItem}
                                                            onCustomAdd={addCustomVegItem}
                                                            customItems={customVegItems}
                                                            onCustomRemove={removeCustomVegItem}
                                                        />

                                                        <MenuItemSelector
                                                            title="Non-Veg Menu Items"
                                                            items={NON_VEG_ITEMS}
                                                            selectedItems={nonVegItems}
                                                            onToggle={toggleNonVegItem}
                                                            onCustomAdd={addCustomNonVegItem}
                                                            customItems={customNonVegItems}
                                                            onCustomRemove={removeCustomNonVegItem}
                                                        />
                                                    </div>
                                                </>
                                            )}
                                        </div>

                                        {/* Right Column - Basic Info & Pricing */}
                                        <div className="space-y-4">
                                            {/* Basic Information */}
                                            <div className="space-y-4">
                                                <h2 className="font-serif text-2xl font-bold text-gray-800 flex items-center gap-2">
                                                    <span className="bg-blue-100 text-blue-800 rounded-full p-1">
                                                        <FaInfoCircle size={20} />
                                                    </span>
                                                    Basic Information
                                                </h2>

                                                <div className="space-y-4">
                                                    <div className="space-y-1">
                                                        <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-1">
                                                            Mess Name <span className="text-red-500">*</span>
                                                        </label>
                                                        <Input
                                                            placeholder="e.g., Homely Mess"
                                                            value={name}
                                                            onChange={e => setName(e.target.value)}
                                                            required
                                                            className="border-2 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                        />
                                                    </div>

                                                    <div className="space-y-1">
                                                        <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-1">
                                                            Location Address <span className="text-red-500">*</span>
                                                        </label>
                                                        {isMapsAvailable ? (
                                                            <Autocomplete
                                                                onLoad={(ref) => (searchBoxRef.current = ref)}
                                                                onPlaceChanged={handlePlaceSelect}
                                                                options={{
                                                                    componentRestrictions: { country: 'in' },
                                                                    fields: ['formatted_address', 'geometry', 'name'],
                                                                }}
                                                            >
                                                                <Input
                                                                    placeholder="Search for your mess address..."
                                                                    value={address}
                                                                    onChange={e => setAddress(e.target.value)}
                                                                    required
                                                                    className="border-2 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                                />
                                                            </Autocomplete>
                                                        ) : (
                                                            <Input
                                                                placeholder="Enter your mess address..."
                                                                value={address}
                                                                onChange={e => setAddress(e.target.value)}
                                                                required
                                                                className="border-2 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                            />
                                                        )}
                                                        <p className="text-xs text-gray-500 mt-1">
                                                            Search your address, then drag the pin on the map below to the exact building location.
                                                        </p>
                                                    </div>

                                                    {/* Interactive Map with Draggable Pin */}
                                                    <div className="space-y-2">
                                                        <label className="font-serif text-lg font-bold text-gray-800 flex items-center gap-2">
                                                            <FaMapPin className="text-green-700" /> Pinpoint Location
                                                        </label>
                                                        <div className="relative w-full h-[300px] overflow-hidden rounded-xl border-2 border-gray-300 shadow-md">
                                                            {isMapsAvailable && isLoaded && !loadError && !mapError ? (
                                                                <GoogleMap
                                                                    mapContainerStyle={{ width: '100%', height: '100%' }}
                                                                    center={location || mapCenter}
                                                                    zoom={location ? 16 : 12}
                                                                    onClick={handleMapClick}
                                                                    onLoad={handleMapLoad}
                                                                    onUnmount={() => setMapInstance(null)}
                                                                    onError={handleMapError}
                                                                    options={{
                                                                        streetViewControl: false,
                                                                        mapTypeControl: true,
                                                                        mapTypeControlOptions: {
                                                                            style: window.google?.maps?.MapTypeControlStyle?.DEFAULT,
                                                                            position: window.google?.maps?.ControlPosition?.TOP_RIGHT,
                                                                        },
                                                                        fullscreenControl: false,
                                                                        mapId: MAP_ID
                                                                    }}
                                                                >
                                                                    <AdvancedMarker
                                                                        position={location || mapCenter}
                                                                        map={mapInstance}
                                                                        draggable={true}
                                                                        onDragEnd={handleMarkerDragEnd}
                                                                        onMarkerError={handleMarkerError}
                                                                    />
                                                                </GoogleMap>
                                                            ) : (
                                                                <div className="w-full h-full bg-gray-100 border-2 border-dashed border-gray-300 rounded-xl flex flex-col items-center justify-center">
                                                                    <MapPin className="h-8 w-8 text-gray-400 mb-2" />
                                                                    <span className="text-gray-500 text-sm">Map preview unavailable</span>
                                                                </div>
                                                            )}
                                                        </div>
                                                        {location && (
                                                            <p className="text-xs text-gray-500 font-mono bg-gray-50 px-3 py-2 rounded-lg border border-gray-200">
                                                                📍 {location.lat.toFixed(6)}, {location.lng.toFixed(6)}
                                                            </p>
                                                        )}
                                                    </div>

                                                    <div className="space-y-1">
                                                        <label className="font-serif text-lg font-bold text-gray-800">
                                                            Description
                                                        </label>
                                                        <Textarea
                                                            placeholder="Describe your mess, amenities, special features, timings, etc."
                                                            value={description}
                                                            onChange={e => setDescription(e.target.value)}
                                                            className="min-h-[120px] border-2 focus:border-primary focus:ring-2 focus:ring-primary/20"
                                                        />
                                                        <p className="text-xs text-gray-500">
                                                            Include details like mess timings, special amenities (AC, Wi-Fi), parking availability, and any rules.
                                                        </p>
                                                    </div>
                                                </div>
                                            </div>

                                            {/* Pricing Section */}
                                            <div className="space-y-4 pt-6 border-t border-gray-200">
                                                <h2 className="font-serif text-2xl font-bold text-gray-800 flex items-center gap-2">
                                                    <span className="bg-rose-100 text-rose-800 rounded-full p-1">
                                                        <FaRupeeSign size={20} />
                                                    </span>
                                                    Pricing Details
                                                </h2>

                                                <PricingOptions
                                                    fullTiffin2TimePrice={fullTiffin2TimePrice}
                                                    setFullTiffin2TimePrice={setFullTiffin2TimePrice}
                                                    halfTiffin2TimePrice={halfTiffin2TimePrice}
                                                    setHalfTiffin2TimePrice={setHalfTiffin2TimePrice}
                                                    offerOneTimeMeal={offerOneTimeMeal}
                                                    setOfferOneTimeMeal={setOfferOneTimeMeal}
                                                    fullTiffin1TimePrice={fullTiffin1TimePrice}
                                                    setFullTiffin1TimePrice={setFullTiffin1TimePrice}
                                                    halfTiffin1TimePrice={halfTiffin1TimePrice}
                                                    setHalfTiffin1TimePrice={setHalfTiffin1TimePrice}
                                                />
                                            </div>
                                        </div>
                                    </div>

                                    {/* Form Actions */}
                                    <div className="pt-6 border-t border-gray-200 flex flex-col-reverse sm:flex-row sm:justify-between gap-4">
                                        <Button
                                            type="button"
                                            variant="destructive"
                                            onClick={() => {
                                                setName('');
                                                setDescription('');
                                                setLocation(null);
                                                setAddress('');
                                                setSelectedMessType('veg');
                                                setCoverPhoto(null);
                                                setOtherPhotos([]);
                                                setCoverPhotoPreview(null);
                                                setOtherPhotosPreviews([]);

                                                // Reset menu states
                                                setVegItems([]);
                                                setNonVegItems([]);
                                                setNonVegDays([]);
                                                setCustomVegItems([]);
                                                setCustomNonVegItems([]);

                                                // Reset pricing states
                                                setFullTiffin2TimePrice('');
                                                setHalfTiffin2TimePrice('');
                                                setOfferOneTimeMeal(false);
                                                setFullTiffin1TimePrice('');
                                                setHalfTiffin1TimePrice('');
                                            }}
                                            className="bg-red-500 hover:bg-red-600 text-white font-semibold px-4 py-2"
                                        >
                                            Clear Form
                                        </Button>
                                        <Button
                                            type="submit"
                                            className="bg-primary hover:bg-primary/90 font-bold text-lg px-8 py-3 shadow-lg"
                                            disabled={isLoading}
                                        >
                                            {isLoading ? 'Creating...' : 'Create Mess Listing'}
                                        </Button>
                                    </div>
                                </form>
                            </div>
                        </div>
                    </div>

                    {/* Confirmation Modal */}
                    <Dialog open={isConfirmOpen} onOpenChange={setIsConfirmOpen}>
                        <DialogContent className="sm:max-w-md">
                            <DialogHeader>
                                <DialogTitle className="text-2xl font-serif font-bold text-gray-800">
                                    Confirm Mess Listing
                                </DialogTitle>
                            </DialogHeader>
                            <div className="py-4 space-y-4">
                                <p className="text-gray-600">
                                    You're about to submit your mess listing for approval. Please review the details below:
                                </p>
                                <div className="space-y-3 bg-gray-50 p-4 rounded-lg">
                                    <div className="flex justify-between">
                                        <span className="font-medium">Mess Name:</span>
                                        <span>{name || 'Not provided'}</span>
                                    </div>
                                    <div className="flex justify-between">
                                        <span className="font-medium">Type:</span>
                                        <span className={selectedMessType === 'veg' ? 'text-green-600' : 'text-red-600'}>
                                            {selectedMessType === 'veg' ? 'Pure Vegetarian' : selectedMessType === 'non-veg' ? 'Non-Veg Only' : 'Veg & Non-Veg'}
                                        </span>
                                    </div>

                                    {/* Pricing Details - Updated to show all prices */}
                                    <div className="pt-3 border-t border-gray-300">
                                        <h4 className="font-medium mb-2">Pricing Details:</h4>

                                        {/* Monthly Fees (2 Times) */}
                                        <div className="mb-3">
                                            <h5 className="font-semibold text-sm">Monthly Fees (2 Times Meal)</h5>
                                            <div className="ml-4 space-y-1">
                                                <div className="flex justify-between">
                                                    <span>Full Tiffin (Mandatory):</span>
                                                    <span className="font-bold text-primary">₹{fullTiffin2TimePrice || 'Not set'}</span>
                                                </div>
                                                {halfTiffin2TimePrice && (
                                                    <div className="flex justify-between">
                                                        <span>Half Tiffin (Optional):</span>
                                                        <span className="font-bold text-primary">₹{halfTiffin2TimePrice}</span>
                                                    </div>
                                                )}
                                            </div>
                                        </div>

                                        {/* One Time Meal Plan */}
                                        {offerOneTimeMeal && (
                                            <div>
                                                <h5 className="font-semibold text-sm">Monthly Fees (1 Time Meal)</h5>
                                                <div className="ml-4 space-y-1">
                                                    <div className="flex justify-between">
                                                        <span>Full Tiffin (Mandatory):</span>
                                                        <span className="font-bold text-primary">₹{fullTiffin1TimePrice || 'Not set'}</span>
                                                    </div>
                                                    {halfTiffin1TimePrice && (
                                                        <div className="flex justify-between">
                                                            <span>Half Tiffin (Optional):</span>
                                                            <span className="font-bold text-primary">₹{halfTiffin1TimePrice}</span>
                                                        </div>
                                                    )}
                                                </div>
                                            </div>
                                        )}
                                    </div>

                                    <div className="flex justify-between">
                                        <span className="font-medium">Photos:</span>
                                        <span>{1 + otherPhotos.length} photos</span>
                                    </div>
                                </div>
                                {!isEditMode && (
                                    <div className="bg-amber-50 border-l-4 border-amber-400 p-3 rounded-r-lg">
                                        <p className="text-sm text-amber-800 font-medium">
                                            Note: Your listing will be reviewed by our team before going live. You'll receive an email notification once approved.
                                        </p>
                                    </div>
                                )}
                            </div>
                            <DialogFooter className="gap-3">
                                <Button
                                    variant="outline"
                                    onClick={() => setIsConfirmOpen(false)}
                                    className="border-gray-300 hover:bg-gray-50"
                                >
                                    Cancel
                                </Button>
                                <Button
                                    onClick={handleConfirmSubmit}
                                    className="bg-primary hover:bg-primary/90 min-w-[120px]"
                                    disabled={isLoading}
                                >
                                    {isLoading ? 'Submitting...' : isEditMode ? 'Update Mess' : 'Confirm & Submit'}
                                </Button>
                            </DialogFooter>
                        </DialogContent>
                    </Dialog>
                </>
            )}
        </div>
    );
};

export default CreateMessForm;
